oxy_webhelp_navlinks = {"salesforce_archiving-d39536e45792":{"topics":[{"title":"Salesforce archival workflow","shortdesc":"<p class=\"shortdesc\">A typical Salesforce archival workflow takes you from connecting your Salesforce         organization through creating and activating an archival policy to monitoring jobs and         restoring records when needed.<\/p>","href":"salesforce\/salesforce_archiving_workflow.html","attributes":{"data-id":"salesforce_archiving_workflow"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_workflow-d39536e45803","topics":[]},{"title":"Salesforce Archiving prerequisites","shortdesc":"<p class=\"shortdesc\">Salesforce Archiving requires a specific Salesforce add-on, API connectivity, and         user permissions before you can configure archival policies.<\/p>","href":"salesforce\/salesforce_archiving_prerequisites.html","attributes":{"data-id":"salesforce_archiving_prerequisites"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_prerequisites-d39536e45814","topics":[]},{"title":"Creating a Salesforce archival policy","shortdesc":"<p class=\"shortdesc\">Create an archival policy to define which Salesforce records are moved to lower-cost         storage, how related records are handled, when the policy runs, and how long archived data         is retained.<\/p>","href":"salesforce\/salesforce_archiving_creating_policy.html","attributes":{"data-id":"salesforce_archiving_creating_policy"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_creating_policy-d39536e45825","topics":[]},{"title":"Salesforce archival policy management","shortdesc":"<p class=\"shortdesc\">After creating archival policies, you can clone, run, edit, enable or disable         schedules, or delete them from the Archive Policies page.<\/p>","href":"salesforce\/salesforce_archiving_policy_management.html","attributes":{"data-id":"salesforce_archiving_policy_management"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_policy_management-d39536e45836","next":"salesforce_archiving_policy_management-d39536e45836"},{"title":"Unarchiving Salesforce records","shortdesc":"<p class=\"shortdesc\">Unarchive one or more archived Salesforce records to recover them to their original         Salesforce organization.<\/p>","href":"salesforce\/salesforce_archiving_restoring_records.html","attributes":{"data-id":"salesforce_archiving_restoring_records"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_restoring_records-d39536e45913","topics":[]},{"title":"Monitoring Salesforce archival jobs","shortdesc":"<p class=\"shortdesc\">Monitor archival job activity, review storage reclaimed, and track policy run history         from the archive dashboard and the policy detail page in <span class=\"ph\">RSC<\/span>.<\/p>","href":"salesforce\/salesforce_archiving_monitoring_audit.html","attributes":{"data-id":"salesforce_archiving_monitoring_audit"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_monitoring_audit-d39536e45924","topics":[]},{"title":"Installing the Rubrik Archiving Lightning Web Component","shortdesc":"<p class=\"shortdesc\">Install and configure the Rubrik Archiving Lightning Web Component to view, search,         and restore archived records directly from Salesforce record pages.<\/p>","href":"salesforce\/salesforce_archiving_installing_lwc.html","attributes":{"data-id":"salesforce_archiving_installing_lwc"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving_installing_lwc-d39536e45938","topics":[]}]}};